window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[314]={"id":"314","numero":314,"titre":"Tumeurs de la vessie","objectifs":[{"id":"314-1","rang":"A","rubrique":"Définition","titre":"Connaître le principal type histologique de tumeur vésicale","contenu":"<p>Le <span class=\"kw-def\">carcinome urothélial</span> (anciennement <em><span class=\"kw-clinique\">carcinome</span> transitionnel</em>) représente à lui seul <span class=\"kw-chiffre\">95 %</span> des tumeurs vésicales. Il dérive de l'<span class=\"kw-def\">urothélium</span>, épithélium de revêtement de l'ensemble de l'arbre urinaire (<span class=\"kw-clinique\">calices</span>, <span class=\"kw-clinique\">pyélons</span>, <span class=\"kw-clinique\">uretères</span>, <span class=\"kw-clinique\">urètre</span>, <span class=\"kw-clinique\">vessie</span>). La vessie est touchée préférentiellement dans <span class=\"kw-chiffre\">90 %</span> des cas, en raison de la <strong>surface importante</strong> de l'urothélium vésical et du <strong>temps de <span class=\"kw-def\">contact</span> prolongé</strong> avec <span class=\"kw-clinique\">les</span> carcinogènes urinaires (organe de stockage et de capacitation).</p>\n      <p>La maladie urothéliale est par essence <span class=\"kw-alerte\">multifocale</span> et peut toucher de manière <strong>synchrone</strong> (au même moment) ou <strong>métachrone</strong> (à distance) l'ensemble de l'arbre urinaire — d'où l'exploration systématique du haut appareil par <span class=\"kw-imagerie\">Uro-TDM</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Type histologique</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Carcinome urothélial</span> <span class=\"kw-chiffre\">(95 %)</span></td>\n            <td>\n              <strong>Origine :</strong> urothélium ; épithélium de revêtement de tout l'arbre urinaire.<br>\n              <strong>Localisations :</strong> vessie <span class=\"kw-chiffre\">90 %</span> ; calices ; pyélons ; uretères ; urètre.<br>\n              <strong>Caractère :</strong> <span class=\"kw-alerte\">multifocal</span> ; lésions synchrones ou métachrones possibles.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Carcinome épidermoïde</span> <span class=\"kw-chiffre\">(&lt; 5 %)</span></td>\n            <td>\n              <strong><span class=\"kw-def\">Terrain</span> :</strong> zones d'endémie de la <span class=\"kw-clinique\">bilharziose urinaire</span> (Égypte ; Moyen-Orient).<br>\n              <strong>Autres causes :</strong> exposition au <span class=\"kw-ttt\">cyclophosphamide</span> ; irritation vésicale chronique.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Adénocarcinome</span> <span class=\"kw-chiffre\">(&lt; 5 %)</span></td>\n            <td>\n              <strong>Prise en charge :</strong> proche des cancers digestifs de même <span class=\"kw-bio\">histologie</span>.\n            </td>\n          </tr>\n          <tr>\n            <td>Formes exceptionnelles <span class=\"kw-chiffre\">(&lt; 1 %)</span></td>\n            <td>\n              <strong>Variants :</strong> <span class=\"kw-clinique\">carcinome</span> micro-papillaire ; carcinomes neuroendocrines ; sarcomes.<br>\n              <strong><span class=\"kw-def\">Pronostic</span> :</strong> souvent <span class=\"kw-alerte\">défavorable</span>, agressivité accrue.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> <strong>lésions pré-cancéreuses</strong> suivent un continuum <span class=\"kw-def\">hyperplasie</span> → <span class=\"kw-def\">atypie</span> → <span class=\"kw-def\">dysplasie</span> → <span class=\"kw-def\">cancer</span>. Le <span class=\"kw-def\">carcinome in situ (CIS)</span> est une <span class=\"kw-clinique\">lésion</span> <span class=\"kw-alerte\">maligne de haut grade</span>, plane, et constitue le piège diagnostique majeur (voir obj-2).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 311 — Tumeur rénale</em></p>","frequence":1},{"id":"314-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie et les facteurs de risque des tumeurs vésicales","contenu":"<p>Le cancer de la vessie représente le <span class=\"kw-chiffre\">5ᵉ cancer</span> en France, avec environ <span class=\"kw-chiffre\">12 000 cas/an</span> et <span class=\"kw-chiffre\">~5 000 décès/an</span> (<span class=\"kw-chiffre\">7ᵉ cause de mortalité par cancer</span>). Son <span class=\"kw-def\">incidence</span> est en <strong>augmentation</strong>, en particulier chez la femme, conséquence de l'<span class=\"kw-clinique\">évolution</span> de l'<span class=\"kw-clinique\">intoxication tabagique</span> féminine — l'<strong>écart H/F se resserre progressivement</strong>. Le <span class=\"kw-def\">terrain</span> habituel est celui d'un <strong>sujet âgé</strong> (âge moyen <span class=\"kw-chiffre\">70 ans</span>) avec une <strong>prédominance masculine</strong> nette (<span class=\"kw-chiffre\">4 H / 1 F</span>).</p>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">facteurs de risque</span> se répartissent en quatre grandes catégories : <strong>FR comportemental</strong> (<span class=\"kw-etio\">tabac</span>), <strong>FR personnels</strong> (ATCD urothélial, Lynch), <strong>FR irritatifs/inflammatoires</strong>, et <strong>FR professionnels</strong> (objectif dédié obj-3).</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Facteur de risque</span></th><th>Mécanisme / Effet</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Tabac</span> <em>(FR principal)</em></td>\n            <td>\n              <strong>Impact :</strong> multiplie le risque de tumeur vésicale <span class=\"kw-chiffre\">× 3</span>.<br>\n              <strong>Mécanisme :</strong> amines aromatiques et hydrocarbures de la fumée concentrés et excrétés dans <span class=\"kw-clinique\">les</span> urines.\n            </td>\n          </tr>\n          <tr>\n            <td>ATCD de tumeur de l'appareil urinaire</td>\n            <td>\n              <strong>Caractère :</strong> <span class=\"kw-alerte\">multifocalité</span> de la maladie urothéliale (haut et bas appareil).<br>\n              <strong>Conséquence :</strong> tumeurs synchrones ou métachrones possibles, <span class=\"kw-def\">surveillance</span> prolongée.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Syndrome de Lynch</span></td>\n            <td>\n              <strong><span class=\"kw-etio\">Génétique</span> :</strong> mutation des gènes du mismatch repair (MMR) ; transmission autosomique dominante.<br>\n              <strong>Spectre :</strong> côlon ; endomètre ; voies excrétrices urinaires (urothélium haut appareil++).\n            </td>\n          </tr>\n          <tr>\n            <td>Inflammation / irritation vésicale chronique</td>\n            <td>\n              <strong>Bilharziose urinaire :</strong> <em>(<span class=\"kw-clinique\">carcinome</span> épidermoïde)</em> ; zones d'endémie Égypte / Moyen-Orient.<br>\n              <strong>Sondage vésical chronique :</strong> neurovessies ; vessies neurologiques.<br>\n              <strong><span class=\"kw-ttt\">Radiothérapie</span> pelvienne :</strong> latence souvent <span class=\"kw-chiffre\">&gt; 5 ans</span>.<br>\n              <strong><span class=\"kw-ttt\">Cyclophosphamide</span> :</strong> <span class=\"kw-ttt\">chimiothérapie alkylante</span> ; <em>(carcinome épidermoïde)</em>.\n            </td>\n          </tr>\n          <tr>\n            <td>Expositions professionnelles <em>(cf. obj-3)</em></td>\n            <td>\n              <strong>Reconnaissance MP :</strong> possible ; à rechercher <span class=\"kw-alerte\">systématiquement</span> à l'interrogatoire.<br>\n              <strong>Familles :</strong> amines aromatiques ; solvants chlorés ; hydrocarbures aromatiques polycycliques.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Toute tumeur vésicale chez un <strong>non-fumeur</strong> sans <span class=\"kw-def\">facteur de risque</span> évident impose une <span class=\"kw-alerte\">enquête professionnelle minutieuse</span> — la latence entre exposition et tumeur peut atteindre <span class=\"kw-chiffre\">20 à 30 ans</span> (voir item 184).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 311 — Tumeur rénale · 184 — Accident — maladie professionnel · 292 — Diagnostic des cancers</em></p>","frequence":2},{"id":"314-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales lésions tissulaires précancéreuses","contenu":"<p>La cancérogenèse urothéliale suit un <strong>continuum lésionnel</strong> bien défini : <span class=\"kw-def\">hyperplasie</span> → <span class=\"kw-def\">atypie</span> → <span class=\"kw-def\">dysplasie</span> → <span class=\"kw-def\">cancer</span>. Ce continuum justifie la stratégie de <span class=\"kw-alerte\">surveillance prolongée</span> par cytologie urinaire et cystoscopie chez <span class=\"kw-clinique\">les</span> patients à risque.</p>\n      <p>Le <span class=\"kw-def\">carcinome in situ (CIS)</span> représente le piège diagnostique majeur de cette filière. Ses caractéristiques essentielles à retenir :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-alerte\">plane</span> (non papillaire, non bourgeonnante).</li>\n        <li><span class=\"kw-alerte\">Invisible</span> à l'<span class=\"kw-imagerie\">imagerie de coupe</span> (<span class=\"kw-imagerie\">TDM</span>, <span class=\"kw-imagerie\">IRM</span>) — non visualisable par <span class=\"kw-clinique\">les</span> examens morphologiques.</li>\n        <li><span class=\"kw-alerte\">Toujours de haut grade</span>, donc agressive par définition.</li>\n        <li>Peut être <strong>isolée</strong> ou <strong>associée</strong> à des tumeurs papillaires (Ta / T1 / T2…).</li>\n      </ul>\n      <div class=\"callout callout-danger\">🚨 Le <span class=\"kw-def\">CIS</span> est <span class=\"kw-alerte\">invisible à l'imagerie</span> mais <span class=\"kw-alerte\">toujours de haut grade</span>. Son diagnostic repose sur la <span class=\"kw-bio\">cytologie urinaire</span> + la <span class=\"kw-imagerie\">cystoscopie</span> (zones érythémateuses suspectes) + <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-bio\">biopsies</span> randomisées</strong> de la muqueuse vésicale — jamais sur la <span class=\"kw-imagerie\">TDM</span> seule.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers</em></p>","frequence":0},{"id":"314-4","rang":"B","rubrique":"Etiologie","titre":"Connaître les expositions professionnelles prédisposantes","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-def\">facteurs de risque</span> professionnels</strong> font partie de l'enquête systématique devant toute tumeur de vessie. Leur identification est <span class=\"kw-alerte\">médico-légalement essentielle</span> car elle ouvre droit à la <span class=\"kw-def\">reconnaissance en maladie professionnelle</span> (MP) et à une indemnisation du patient. La <strong>latence</strong> entre exposition et survenue <span class=\"kw-etio\">tumorale</span> est longue, classiquement <span class=\"kw-chiffre\">20 à 30 ans</span>, avec une exposition pertinente d'au moins <span class=\"kw-chiffre\">5 ans</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Famille</th><th>Secteurs concernés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Amines aromatiques</span></td>\n            <td>\n              <strong>Colorants :</strong> teinture ; industrie textile.<br>\n              <strong>Caoutchouc :</strong> pneu de voiture ; industrie du caoutchouc.<br>\n              <strong>Chimie / pharma :</strong> industrie pharmaceutique ; pétrochimie ; plasturgie.<br>\n              <strong>Énergie :</strong> mines de charbon.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Solvants chlorés</span></td>\n            <td>\n              <strong>Imprimerie :</strong> fabrication des encres ; fabrication des colles.<br>\n              <strong>Nettoyage :</strong> nettoyage à sec ; pressing.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hydrocarbures aromatiques polycycliques (HAP)</span></td>\n            <td>\n              <strong>Combustibles fossiles :</strong> goudrons ; huiles et brais de houille ; combustion du charbon.<br>\n              <strong>Métallurgie :</strong> production d'aluminium ; production de coke ; industries du fer et de l'acier.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">🚨 Devant toute tumeur vésicale, <span class=\"kw-alerte\">l'interrogatoire professionnel est systématique</span> (≥ <span class=\"kw-chiffre\">5 ans</span> d'exposition pertinente ; latence <span class=\"kw-chiffre\">20 à 30 ans</span>). La <span class=\"kw-def\">reconnaissance en maladie professionnelle</span> est un droit du patient et conditionne son indemnisation — ne pas l'oublier dans le bilan initial.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 182 — Environnement professionnel, sécurité au travail · 184 — Accident — maladie professionnel</em></p>","frequence":0},{"id":"314-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes fonctionnels (hématurie et autres signes fonctionnels) révélateurs d’une tumeur de vessie et les anomalies de l’examen clinique associées","contenu":"<div class=\"callout callout-danger\">🚨 <strong>DOGME</strong> — Toute <span class=\"kw-clinique\">hématurie</span> <span class=\"kw-alerte\">macroscopique</span> OU <span class=\"kw-alerte\">microscopique</span> doit faire rechercher une tumeur de la <strong>vessie</strong> / <strong>rein</strong> / <strong>uretère</strong>. Cette règle s'applique quel que soit l'âge, le sexe et l'aspect (caillots ou non).</div>\n      <p>Le diagnostic est dans l'immense majorité des cas <strong>fait à partir de points d'appel cliniques</strong> ; la découverte fortuite est rare. La présentation clinique se structure en trois grands niveaux à connaître : <strong>présentation initiale</strong>, <strong>extension locorégionale</strong>, <strong>extension métastatique</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Niveau</th><th>Anomalies à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Présentation initiale</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Hématurie</span> macroscopique :</strong> <span class=\"kw-alerte\">signe révélateur le plus fréquent</span> <span class=\"kw-chiffre\">(80 %)</span>, avec caillots. La <strong>chronologie</strong> oriente : <span class=\"kw-clinique\">hématurie terminale</span> = origine <strong>vésicale</strong> probable ; <span class=\"kw-clinique\">hématurie totale</span> = origine non localisée (haut OU bas appareil) ; <span class=\"kw-clinique\">hématurie initiale</span> = origine urétro-prostatique. À retenir comme classique QCM.<br>\n              <strong>Signes irritatifs vésicaux <span class=\"kw-chiffre\">(20 %)</span> :</strong> <span class=\"kw-clinique\">pollakiurie</span> ; <span class=\"kw-clinique\">urgenturie</span> ; <span class=\"kw-clinique\">brûlures mictionnelles</span> — évocateurs si <strong>apparition récente</strong> et persistant <strong>après élimination d'une <span class=\"kw-def\">infection urinaire</span></strong> (<span class=\"kw-bio\">ECBU</span> stérile).<br>\n              <strong>Syndrome anémique clinique :</strong> <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">pâleur</span> ; <span class=\"kw-clinique\">dyspnée d'effort</span> ; signes d'une spoliation sanguine chronique ou aiguë.\n            </td>\n          </tr>\n          <tr>\n            <td>Extension locorégionale</td>\n            <td>\n              <strong>Douleurs pelviennes :</strong> sourdes ; profondes ; évocatrices d'<span class=\"kw-bio\">envahissement</span> local.<br>\n              <strong>Douleurs lombaires :</strong> par <strong>dilatation des cavités pyélocalicielles</strong> secondaire à une obstruction mécanique — soit obstruction du <strong>méat urétéral</strong> par la tumeur, soit obstruction de l'<strong>uretère</strong> par <span class=\"kw-clinique\">adénopathie</span> iliaque ou lombo-aortique.<br>\n              <strong>Examen clinique :</strong> <span class=\"kw-clinique\">blindage pelvien</span> au toucher rectal (TR) ; <span class=\"kw-clinique\">masse hypogastrique</span> palpable (tumeur volumineuse).\n            </td>\n          </tr>\n          <tr>\n            <td>Extension métastatique</td>\n            <td>\n              <strong><span class=\"kw-clinique\">AEG</span> :</strong> <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">amaigrissement</span> ; <span class=\"kw-alerte\">signes cliniques de dénutrition</span>.<br>\n              <strong><span class=\"kw-clinique\">Adénopathies</span> :</strong> <span class=\"kw-alerte\">adénopathies sus-claviculaires</span> (signal d'alerte métastatique).<br>\n              <strong>Métastases pulmonaires :</strong> <span class=\"kw-clinique\">signes pulmonaires</span> (<span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">hémoptysie</span>).<br>\n              <strong>Métastases osseuses :</strong> <span class=\"kw-clinique\">douleurs osseuses</span> ; fractures pathologiques possibles.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le bilan paraclinique de l'<span class=\"kw-clinique\">hématurie</span> évocatrice d'une origine urologique est codifié : <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">bilan d'hémostase</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-imagerie\">échographie réno-vésicale</span> ; <span class=\"kw-imagerie\">Uro-TDM</span> (ou <span class=\"kw-imagerie\">Uro-IRM</span> à défaut) qui est l'<strong>examen morphologique de référence</strong> pour l'exploration de l'ensemble de l'appareil urothélial.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-clinique\">Hématurie</span> · 311 — Tumeur rénale</em></p>","frequence":0},{"id":"314-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’indication d’une résection trans-urétrale de vessie","contenu":"<p>La <span class=\"kw-def\">résection trans-urétrale de vessie (RTUV)</span> est le geste chirurgical endoscopique <span class=\"kw-alerte\">indispensable</span> au diagnostic et à la prise en charge initiale de toute tumeur vésicale. Elle constitue le pivot de la stratégie thérapeutique : c'est elle qui apporte la <strong>preuve histologique</strong> du cancer, qui détermine le <strong><span class=\"kw-def\">stade</span> T</strong> (<span class=\"kw-bio\">envahissement</span> pariétal) et le <strong><span class=\"kw-def\">grade</span> <span class=\"kw-etio\">tumoral</span></strong>, et qui distingue ainsi <span class=\"kw-def\">TVNIM</span> de <span class=\"kw-def\">TVIM</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Objectifs</td>\n            <td>\n              <strong>Diagnostic :</strong> <span class=\"kw-bio\">anatomopathologique</span> de certitude des lésions et de leur type histologique.<br>\n              <strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">stade</span> <span class=\"kw-etio\">tumoral</span> (profondeur d'<span class=\"kw-bio\">envahissement</span>) ; grade tumoral ; distinction <span class=\"kw-def\">TVNIM</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">TVIM</span> selon envahissement ou non du muscle.<br>\n              <strong>Thérapeutique :</strong> en cas de <span class=\"kw-def\">TVNIM</span>, c'est souvent le <strong>seul geste chirurgical nécessaire</strong> ; oriente vers <span class=\"kw-clinique\">les</span> traitements complémentaires éventuels (instillations endovésicales).\n            </td>\n          </tr>\n          <tr>\n            <td>Préalable</td>\n            <td>\n              <strong><span class=\"kw-ttt\">Anticoagulants</span> :</strong> arrêt ou relais selon la molécule et le risque thromboembolique.<br>\n              <strong>Urines :</strong> vérification de la <span class=\"kw-alerte\">stérilité des urines</span> par <span class=\"kw-bio\">ECBU</span> avant le geste.\n            </td>\n          </tr>\n          <tr>\n            <td>Modalités</td>\n            <td>\n              <strong>Cadre :</strong> intervention chirurgicale programmée au bloc opératoire.<br>\n              <strong>Anesthésie :</strong> générale OU locorégionale.<br>\n              <strong>Matériel :</strong> endoscope rigide trans-urétral.<br>\n              <strong>Geste :</strong> résection <span class=\"kw-alerte\">complète</span> (≠ <span class=\"kw-bio\">biopsie</span>) ; <span class=\"kw-alerte\">suffisamment profonde pour emporter le détrusor</span> ; sans perforer la vessie ; respect des méats urétéraux non envahis.\n            </td>\n          </tr>\n          <tr>\n            <td>Pièce opératoire</td>\n            <td>\n              <strong>Type :</strong> copeaux de résection (ou pièce monobloc selon technique).<br>\n              <strong>Analyse :</strong> envoi systématique en <span class=\"kw-bio\">anatomopathologie</span> ; détermine type histologique, <span class=\"kw-def\">stade</span> T, grade.\n            </td>\n          </tr>\n          <tr>\n            <td>Complications</td>\n            <td>\n              <strong><span class=\"kw-alerte\">Perforation vésicale</span> :</strong> rare si geste prudent ; impose <span class=\"kw-ttt\">drainage</span> prolongé.<br>\n              <strong>Syndrome de <span class=\"kw-def\">TURP</span> / réabsorption :</strong> hyponatrémie de dilution ; rare avec sérum physiologique.<br>\n              <strong><span class=\"kw-clinique\">Hématurie</span> post-opératoire :</strong> nécessite parfois irr<span class=\"kw-chiffre\">iga</span>tion vésicale continue.<br>\n              <strong><span class=\"kw-clinique\">Infection urinaire</span> :</strong> prévenue par <span class=\"kw-bio\">ECBU</span> stérile pré-op.\n            </td>\n          </tr>\n          <tr>\n            <td>Résection « de second look »</td>\n            <td>\n              <strong>Délai :</strong> <span class=\"kw-chiffre\">4 à 6 semaines</span> après la RTUV initiale.<br>\n              <strong>Indications :</strong> résection probablement incomplète (tumeur volumineuse) ; risque de méconnaître une <span class=\"kw-def\">TVIM</span> (tumeur affleurant le muscle [<span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">T1</span>] ou résection insuffisamment profonde où le détrusor n'est pas visualisé sur <span class=\"kw-clinique\">les</span> copeaux).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ <strong>Instillation endovésicale précoce de <span class=\"kw-ttt\">mitomycine C</span></strong> : recommandée dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">24 h</span> post-RTUV pour les <span class=\"kw-def\">TVNIM</span> à faible risque — réduit significativement le taux de récidive. À distinguer du protocole d'instillations itératives (Mitomycine ou <span class=\"kw-ttt\">BCG</span>) débuté secondairement selon le risque de récidive/progression.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/314/tnm-vessie.png\" alt=\"Classification TNM des tumeurs vésicales — coupe transversale de la paroi vésicale (urothélium, chorion, muscle superficiel, muscle profond, tissu adipeux) avec les stades Tis, Ta, T1(a-b), T2, T3a, T3b, T4a-T4b. Distinction TVNIM (Tis/Ta/T1) vs TVIM (≥T2).\">\n        <figcaption><strong><span class=\"kw-def\">Classification</span> TNM des tumeurs vésicales</strong> — <span class=\"kw-def\">TVNIM</span> (Tis, Ta, T1) = tumeur non infiltrant le muscle, prise en charge endoscopique. <span class=\"kw-def\">TVIM</span> (≥ T2) = tumeur infiltrant le muscle, prise en charge par cystectomie ± <span class=\"kw-ttt\">chimiothérapie</span>.</figcaption>\n      </figure>\n      <p>La distinction <span class=\"kw-def\">TVNIM</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">TVIM</span> à partir de la RTUV conditionne toute la stratégie thérapeutique :</p>\n      <table >\n        <thead>\n          <tr><th>TVNIM <span class=\"kw-chiffre\">(80 %)</span></th><th>TVIM <span class=\"kw-chiffre\">(20 %)</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong>Stades :</strong> Ta (tumeur papillaire sans <span class=\"kw-ttt\">infiltration</span> du chorion) ; Tis (<span class=\"kw-clinique\">carcinome</span> in situ urothélial, plan, <span class=\"kw-alerte\">toujours haut grade</span>) ; T1 (<span class=\"kw-bio\">infiltration</span> du chorion).<br>\n              <strong>Traitement :</strong> <span class=\"kw-ttt\">RTUV</span> ± instillations endovésicales (<span class=\"kw-ttt\">Mitomycine</span> ou <span class=\"kw-ttt\">BCG</span>) selon risque de récidive/progression.\n            </td>\n            <td>\n              <strong>Stades :</strong> T2 (<span class=\"kw-ttt\">infiltration</span> de la musculeuse) ; T3 (graisse périvésicale) ; T4 (organe de voisinage).<br>\n              <strong>Traitement localisé :</strong> <span class=\"kw-ttt\">cystectomie radicale</span> ± <span class=\"kw-ttt\">chimiothérapie</span> adjuvante ; alternative = <span class=\"kw-ttt\">chimio-radiothérapie</span>.<br>\n              <strong>Traitement métastatique :</strong> <span class=\"kw-ttt\">chimiothérapie</span> ± <span class=\"kw-ttt\">immunothérapie</span> ± soins de support.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ La <span class=\"kw-def\">RTUV</span> <span class=\"kw-alerte\">n'identifie pas</span> <span class=\"kw-clinique\">les</span> stades <span class=\"kw-chiffre\">T3</span> ou <span class=\"kw-chiffre\">T4</span> (extension hors muscle) — c'est l'<span class=\"kw-imagerie\">imagerie</span> qui les suspecte, et seule la <strong>pièce de cystectomie</strong> permet la <span class=\"kw-def\">stadification</span> définitive.</div>\n      <div class=\"callout callout-danger\">🚨 Le <span class=\"kw-def\">carcinome in situ (CIS)</span> et toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">TVIM</span> sont <span class=\"kw-alerte\">toujours de haut grade</span> — agressivité d'emblée, <span class=\"kw-def\">pronostic</span> réservé.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0},{"id":"314-7","rang":"B","rubrique":"Diagnostic positif","titre":"Stratégie des examens complémentaires : cytologie urinaire et cystoscopie","contenu":"<p>La stratégie diagnostique devant une tumeur vésicale suspectée associe un <strong>bilan d'<span class=\"kw-clinique\">hématurie</span></strong> standard, une <strong>cytologie urinaire</strong>, et une <strong>cystoscopie</strong>. Chacun de ces examens a un rôle complémentaire et des limites propres qu'il faut connaître précisément pour éviter <span class=\"kw-clinique\">les</span> pièges QCM.</p>\n      <p>Le <strong>bilan d'<span class=\"kw-clinique\">hématurie</span></strong> évocatrice d'une origine urologique comprend (cf. obj-4) : <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">bilan d'hémostase</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">ECBU</span> ; <span class=\"kw-imagerie\">échographie réno-vésicale</span> ; <span class=\"kw-imagerie\">Uro-TDM</span> (ou <span class=\"kw-imagerie\">Uro-IRM</span> à défaut), qui reste l'<strong>examen morphologique de référence</strong> pour l'exploration de l'arbre urothélial.</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Stratégie et limites</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cytologie urinaire</span></td>\n            <td>\n              <strong>Principe :</strong> analyse anatomo-pathologique au microscope d'un échantillon urinaire ; recherche de cellules urothéliales tumorales.<br>\n              <strong>Si normale :</strong> <span class=\"kw-alerte\">n'exclut pas le diagnostic</span> ❌ ; ne dispense pas de contrôles endoscopiques itératifs.<br>\n              <strong>Si positive :</strong> tumeur urothéliale très probable, <span class=\"kw-alerte\">excellente VPP</span> ✅ ; à confirmer et à localiser sur l'appareil urinaire.<br>\n              <strong>Si atypies / matériel insuffisant :</strong> nouvelle <span class=\"kw-bio\">cytologie</span> peut être demandée.<br>\n              <strong>Intérêt spécifique :</strong> <span class=\"kw-alerte\">examen clé du diagnostic de CIS</span> (<span class=\"kw-clinique\">lésion</span> plane invisible en imagerie).\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cystoscopie</span> / <span class=\"kw-def\">Fibroscopie urétro-vésicale</span></td>\n            <td>\n              <strong>Attention :</strong> ne permet habituellement <span class=\"kw-alerte\">pas de diagnostic histologique</span> ❌ — c'est la RTUV qui apporte la preuve.<br>\n              <strong>Indications :</strong> imagerie sans étiologie évidente ; cytologie urinaire positive ; <span class=\"kw-def\">facteurs de risque</span> de tumeur urothéliale ; optionnelle avant RTUV si patient adressé par un généraliste avec imagerie fortement évocatrice (<span class=\"kw-imagerie\">échographie</span> ou <span class=\"kw-imagerie\">TDM</span>).<br>\n              <strong>Préalable :</strong> vérification de la <span class=\"kw-alerte\">stérilité des urines</span> (<span class=\"kw-bio\">ECBU</span>) ✅.<br>\n              <strong>Modalités :</strong> consultation sous anesthésie locale ; fibroscope souple idéalement ; cystoscopie rigide sinon. Optimisation possible par <span class=\"kw-imagerie\">cystoscopie en fluorescence</span> (<span class=\"kw-ttt\">Hexvix</span> / hexaminolévulinate) ou <span class=\"kw-imagerie\">NBI</span> (Narrow Band Imaging) — utile au repérage du <span class=\"kw-def\">CIS</span>, invisible en lumière blanche.<br>\n              <strong>Résultats :</strong> notés sur un <span class=\"kw-imagerie\">schéma de cartographie vésicale</span> — nombre ; taille ; aspect (sessile / pédiculé ; papillaire / solide) ; localisation (trigone ; méats urétéraux ; col vésical) ; muqueuse avoisinante (zones érythémateuses évocatrices de <span class=\"kw-def\">CIS</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Une <span class=\"kw-bio\">cytologie urinaire normale</span> <span class=\"kw-alerte\">n'élimine pas</span> une tumeur de vessie. La <span class=\"kw-imagerie\">cystoscopie</span> reste l'examen clé qui <strong>visualise et localise</strong> la tumeur ; la <span class=\"kw-ttt\">RTUV</span> est celle qui apporte la <strong>confirmation histologique</strong>.</div>\n      <div class=\"callout callout-danger\">🚨 La <span class=\"kw-imagerie\">cystoscopie</span> repère <span class=\"kw-clinique\">les</span> lésions mais <span class=\"kw-alerte\">n'est pas histologique</span> — seule la pièce de <span class=\"kw-ttt\">RTUV</span> donne le diagnostic de certitude (type ; <span class=\"kw-def\">grade</span> ; stade).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-clinique\">Hématurie</span> · 311 — Tumeur rénale · 292 — Diagnostic des cancers</em></p>","frequence":1},{"id":"314-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication des examens d’imagerie d’une tumeur vésicale","contenu":"<p>Le bilan d'imagerie d'une tumeur vésicale dépend du <span class=\"kw-def\">stade</span> T identifié par la <span class=\"kw-def\">RTUV</span> (<span class=\"kw-def\">TVNIM</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">TVIM</span>). L'objectif est double : <strong>rechercher une tumeur synchrone</strong> du haut appareil urinaire (caractère <span class=\"kw-alerte\">multifocal</span> de la maladie urothéliale) et, en cas de TVIM, <strong>évaluer l'extension</strong> locorégionale et métastatique.</p>\n      <table >\n        <thead>\n          <tr><th>TVNIM <span class=\"kw-chiffre\">(80 %)</span></th><th>TVIM <span class=\"kw-chiffre\">(20 %)</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <strong><span class=\"kw-imagerie\">Uro-TDM</span> :</strong> avec temps tardif urinaire (= excrétoire) ; recherche d'une <span class=\"kw-alerte\">tumeur synchrone du haut appareil urinaire</span> ; impératif compte tenu du caractère multifocal de la maladie urothéliale.\n            </td>\n            <td>\n              <strong><span class=\"kw-imagerie\">TDM-TAP</span> injectée :</strong> avec temps tardif urinaire ou excrétoire ; évalue extension locale ; <span class=\"kw-clinique\">adénopathies</span> ; métastases viscérales (foie, poumon).<br>\n              <strong><span class=\"kw-imagerie\">IRM vésicale multiparamétrique</span> :</strong> <span class=\"kw-def\">score</span> <span class=\"kw-def\">VI-RADS</span> (1 à 5) pour l'évaluation de l'<span class=\"kw-bio\">envahissement</span> musculaire avant cystectomie ; complète ou remplace le <span class=\"kw-imagerie\">TDM</span> dans certains centres experts.<br>\n              <strong><span class=\"kw-imagerie\">PET-FDG</span> :</strong> en cas de doute sur métastases (<span class=\"kw-clinique\">adénopathies</span> équivoques en <span class=\"kw-imagerie\">TDM</span> ; bilan pré-cystectomie radicale).<br>\n              <strong><span class=\"kw-imagerie\">TDM cérébrale</span> :</strong> en cas de troubles neurologiques.<br>\n              <strong><span class=\"kw-imagerie\">Scintigraphie osseuse</span> :</strong> en cas de douleurs évocatrices ; anomalie osseuse en <span class=\"kw-imagerie\">TDM</span> ; métastases pulmonaires connues.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le <strong><span class=\"kw-def\">suivi</span> post-thérapeutique</strong> reprend l'imagerie selon le <span class=\"kw-def\">stade</span> initial :</p>\n      <table >\n        <thead>\n          <tr><th>Stade</th><th>Modalités du suivi</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">TVNIM</span></td>\n            <td>\n              <strong><span class=\"kw-imagerie\">Endoscopie</span> + cytologie :</strong> <span class=\"kw-bio\">cytologie urinaire</span> + <span class=\"kw-imagerie\">cystoscopie</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 à 12 mois</span> selon le risque (récidive locale ~<span class=\"kw-chiffre\">50 %</span>).<br>\n              <strong>Imagerie haut appareil :</strong> <span class=\"kw-imagerie\">Uro-TDM</span> tous les <span class=\"kw-chiffre\">2 ans</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">TVIM</span></td>\n            <td>\n              <strong>Imagerie :</strong> <span class=\"kw-imagerie\">TDM-TAP</span> régulier ; <span class=\"kw-def\">surveillance</span> d'une éventuelle <span class=\"kw-clinique\">évolution</span> métastatique (~<span class=\"kw-chiffre\">50 %</span>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">📐 <strong>Critère radiologique clé</strong> pour distinguer T2 <span class=\"kw-bio\">vs</span> T3 sur <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span> : <strong>disparition du liseré graisseux périvésical</strong> = <span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">T3</span> ; <span class=\"kw-bio\">envahissement</span> d'un organe de voisinage (utérus, vagin, prostate, paroi pelvienne) = stade <span class=\"kw-chiffre\">T4</span>. La <span class=\"kw-def\">RTUV</span> ne dépasse pas le stade T2 — c'est l'imagerie qui suspecte T3/T4.</div>\n      <div class=\"callout callout-warn\">⚠️ Le caractère <span class=\"kw-alerte\">multifocal</span> des tumeurs urothéliales (vessie ET haut appareil) impose un <span class=\"kw-imagerie\">Uro-TDM</span> même pour une <span class=\"kw-def\">TVNIM</span> apparemment isolée — une tumeur synchrone du haut appareil change radicalement la stratégie thérapeutique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 260 — <span class=\"kw-clinique\">Hématurie</span> · 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/bladder-cancer","label":"Radiopaedia : Bladder cancer"}]}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-19-item-314-tumeurs-vesicales/","label":"AFU — Chapitre 19 item 314 tumeurs vesicales"}],"cards":[{"i":"2f106a2028dc","n":314,"o":"314-1","u":"Définition","t":"Connaître le principal type histologique de tumeur vésicale","q":"Quelles sont les caractéristiques de la maladie urothéliale en termes de localisation et d'évolutivité ?","a":"<ul><li>La vessie est touchée préférentiellement dans <strong>90 %</strong> des cas, en raison de sa grande surface urothéliale et du temps de contact prolongé avec les carcinogènes urinaires.</li><li>La maladie urothéliale est par essence <strong>multifocale</strong>. Des lésions peuvent apparaître de manière <strong>synchrone</strong> (au même moment) ou <strong>métachrone</strong> (à distance) dans l'ensemble de l'arbre urinaire.</li></ul>"},{"i":"76dea0848862","n":314,"o":"314-1","u":"Définition","t":"Connaître le principal type histologique de tumeur vésicale","q":"Quelle est l'origine du carcinome urothélial ?","a":"<p>Le carcinome urothélial dérive de l'<strong>urothélium</strong>, l'épithélium de revêtement qui tapisse l'ensemble de l'arbre urinaire (calices, pyélons, uretères, urètre, et vessie).</p>"},{"i":"bce3150aed7f","n":314,"o":"314-1","u":"Définition","t":"Connaître le principal type histologique de tumeur vésicale","q":"Quel est le principal type histologique de tumeur vésicale et quelle est sa fréquence relative ?","a":"<p>Le principal type histologique de tumeur vésicale est le <strong>carcinome urothélial</strong> (anciennement carcinome transitionnel). Il représente <strong>95 %</strong> des tumeurs vésicales.</p>"},{"i":"206a4df94937","n":314,"o":"314-5","u":"Diagnostic positif","t":"Connaître les signes fonctionnels (hématurie et autres signes fonctionnels) révélateurs d’une tumeur de vessie et les anomalies de l’examen clinique associées","q":"Quels sont les autres signes fonctionnels, en dehors de l'hématurie macroscopique, pouvant révéler une tumeur de la vessie ?","a":"<p>Outre l'hématurie macroscopique, une tumeur de la vessie peut se révéler par des <strong>signes irritatifs vésicaux</strong> (environ 20% des cas) tels que la <strong>pollakiurie</strong>, l'<strong>urgenturie</strong> et les <strong>brûlures mictionnelles</strong>. Ces signes sont évocateurs s'ils apparaissent récemment et persistent après élimination d'une infection urinaire (ECBU stérile).</p><p>Un <strong>syndrome anémique clinique</strong> (asthénie, pâleur, dyspnée d'effort) peut également être présent en cas de spoliation sanguine chronique ou aiguë.</p>"},{"i":"32e38f0a7eef","n":314,"o":"314-5","u":"Diagnostic positif","t":"Connaître les signes fonctionnels (hématurie et autres signes fonctionnels) révélateurs d’une tumeur de vessie et les anomalies de l’examen clinique associées","q":"Quel est le signe fonctionnel le plus fréquent révélant une tumeur de la vessie, et quelles sont ses caractéristiques classiques ?","a":"<p>Le signe fonctionnel le plus fréquent révélant une tumeur de la vessie est l'<strong>hématurie macroscopique</strong>, présente dans environ <strong>80%</strong> des cas. Elle est souvent accompagnée de <strong>caillots</strong>. La chronologie de l'hématurie peut orienter l'origine :</p><ul><li><strong>Hématurie terminale</strong> : évoque une origine vésicale.</li><li><strong>Hématurie totale</strong> : origine non localisée (haut ou bas appareil urinaire).</li><li><strong>Hématurie initiale</strong> : origine urétro-prostatique.</li></ul>"},{"i":"52e8b29624e2","n":314,"o":"314-5","u":"Diagnostic positif","t":"Connaître les signes fonctionnels (hématurie et autres signes fonctionnels) révélateurs d’une tumeur de vessie et les anomalies de l’examen clinique associées","q":"Quelle est la conduite à tenir systématique devant toute hématurie pour rechercher une éventuelle tumeur de la vessie ?","a":"<p>Toute <strong>hématurie macroscopique ou microscopique</strong>, quel que soit l'âge, le sexe ou l'aspect (caillots ou non), doit systématiquement faire rechercher une tumeur de la vessie, du rein ou de l'uretère.</p>"},{"i":"609cd5d08a8c","n":314,"o":"314-5","u":"Diagnostic positif","t":"Connaître les signes fonctionnels (hématurie et autres signes fonctionnels) révélateurs d’une tumeur de vessie et les anomalies de l’examen clinique associées","q":"Quels sont les signes cliniques évoquant une extension locorégionale ou métastatique d'une tumeur de la vessie ?","a":"<p>Les signes d'extension locorégionale ou métastatique d'une tumeur de la vessie incluent :</p><ul><li><strong>Extension locorégionale</strong> :<ul><li><strong>Douleurs pelviennes</strong> (sourdes, profondes) évoquant un envahissement local.</li><li><strong>Douleurs lombaires</strong> par dilatation des cavités pyélocalicielles due à une obstruction du méat urétéral ou de l'uretère (par adénopathie).</li><li>À l'examen clinique (TR), un <strong>blindage pelvien</strong> ou une <strong>masse hypogastrique palpable</strong> peuvent être retrouvés.</li></ul></li><li><strong>Extension métastatique</strong> :<ul><li><strong>Altération de l'état général (AEG)</strong> avec asthénie, amaigrissement, signes de dénutrition.</li><li><strong>Adénopathies</strong> (notamment sus-claviculaires).</li><li><strong>Métastases pulmonaires</strong> avec toux, dyspnée, hémoptysie.</li><li><strong>Métastases osseuses</strong> avec douleurs osseuses, voire fractures pathologiques.</li></ul></li></ul>"}]};